I = imread('printedtext.png');
bwG = imbinarize(I);
bwA = imbinarize(I, 'adaptive', 'ForegroundPolarity', 'dark', 'Sensitivity', 0.45);
montage({bwG, bwA})

I = imread('coins.png');
[T, EM] = graythresh(I);
fprintf('Threshold %.3f, effectiveness %.3f\n', T, EM);
bw = imbinarize(I, T);

I = imread('circlesBrightDark.png');
thresh = multithresh(I, 2);
seg = imquantize(I, thresh);
imshow(label2rgb(seg))

I = imread('coins.png');
levels = multithresh(I, 3);
values = [0 85 170 255];
q = imquantize(I, levels, values);
imshow(uint8(q))

bw = imfill(imbinarize(imread('coins.png')), 'holes');
[L, n] = bwlabel(bw, 8);
fprintf('%d objects\n', n);
imshow(label2rgb(L, 'jet', 'k', 'shuffle'))

bw = imfill(imbinarize(imread('coins.png')), 'holes');
CC = bwconncomp(bw, 8);
fprintf('NumObjects = %d\n', CC.NumObjects);
numPixels = cellfun(@numel, CC.PixelIdxList);
[~, biggest] = max(numPixels);
L = labelmatrix(CC);

I = imread('coins.png');
bw = imfill(imbinarize(I), 'holes');
T = regionprops('table', bw, I, ...
    {'Area','Centroid','Eccentricity','MeanIntensity','Circularity'});
T = sortrows(T, 'Area', 'descend');
head(T)

bw = imfill(imbinarize(imread('coins.png')), 'holes');
[B, L] = bwboundaries(bw, 'noholes');
imshow(label2rgb(L)); hold on
for k = 1:numel(B)
    plot(B{k}(:,2), B{k}(:,1), 'w', 'LineWidth', 1.5);
end

bw = imbinarize(imread('circles.png'));
D = -bwdist(~bw);
D = imhmin(D, 2);      % suppress shallow minima
L = watershed(D);
L(~bw) = 0;
imshow(label2rgb(L, 'jet', 'w', 'shuffle'))

RGB = imread('kobi.png');
lab = rgb2lab(RGB);
ab = single(lab(:,:,2:3));
[L, C] = imsegkmeans(ab, 3, 'NumAttempts', 5);
imshow(labeloverlay(RGB, L))

I = imread('coins.png');
mask = false(size(I));
mask(50:180, 50:230) = true;
bw = activecontour(I, mask, 300, 'Chan-Vese', 'SmoothFactor', 1.2);
imshow(labeloverlay(I, bw))

A = imread('kobi.png');
[L, N] = superpixels(A, 500);
BW = boundarymask(L);
imshow(imoverlay(A, BW, 'cyan'))
fprintf('%d superpixels\n', N);

A = imread('peppers.png');
L = superpixels(A, 500);
roi = false(size(A,1), size(A,2));
roi(80:330, 180:430) = true;
BW = grabcut(A, L, roi);
imshow(labeloverlay(A, BW))

I = imread('coins.png');
[centers, radii, metric] = imfindcircles(I, [20 45], ...
    'ObjectPolarity', 'bright', 'Sensitivity', 0.92);
imshow(I); viscircles(centers, radii, 'EdgeColor', 'r');
fprintf('Found %d coins\n', numel(radii));

I = imread('coins.png');
[c, r] = imfindcircles(I, [20 45]);
imshow(I); h = viscircles(c, r, 'Color', 'b', 'LineWidth', 2);

I = imread('circuit.tif');
BW = edge(I, 'canny');
[H, T, R] = hough(BW, 'RhoResolution', 0.5, 'Theta', -90:0.5:89);
imshow(imadjust(rescale(H)), 'XData', T, 'YData', R, 'InitialMagnification', 'fit');
axis on, axis normal, xlabel('\theta'), ylabel('\rho')

BW = edge(imread('circuit.tif'), 'canny');
[H, T, R] = hough(BW);
P = houghpeaks(H, 8, 'Threshold', 0.3*max(H(:)));
plot(T(P(:,2)), R(P(:,1)), 's', 'Color', 'white');

I = imread('circuit.tif');
BW = edge(I, 'canny');
[H, T, R] = hough(BW);
P = houghlines(BW, T, R, houghpeaks(H, 10), 'FillGap', 5, 'MinLength', 30);
imshow(I); hold on
for k = 1:numel(P)
    xy = [P(k).point1; P(k).point2];
    plot(xy(:,1), xy(:,2), 'g', 'LineWidth', 2);
end

I = zeros(200); I(50:150, 90:110) = 1;
theta = 0:179;
[R, xp] = radon(I, theta);
imagesc(theta, xp, R); colormap(hot); colorbar
rec = iradon(R, theta, 'linear', 'Ram-Lak');

P = phantom(256);
theta = 0:0.5:179.5;
R = radon(P, theta);
rec = iradon(R, theta, 'linear', 'Shepp-Logan', 0.8, 256);
montage({P, rescale(rec)})

I = im2double(imread('cameraman.tif'));
J = dct2(I);
J(abs(J) < 0.05) = 0;            % keep only large coefficients
K = idct2(J);
fprintf('Nonzero coeffs: %.1f%%\n', 100*nnz(J)/numel(J));
montage({I, K})

I = im2double(imread('rice.png'));
C = dct2(I);
mask = false(size(C)); mask(1:40, 1:40) = true;
rec = idct2(C .* mask);
imshow(rec, [])

I = imread('cameraman.tif');
fun = @(bs) std2(bs.data) * ones(size(bs.data));
B = blockproc(I, [16 16], fun);
imshow(B, [])

A = imread('kobi.png');
L = superpixels(A, 400);
mask = boundarymask(L);
imshow(imoverlay(A, mask, 'yellow'))

bw = imfill(imbinarize(imread('coins.png')), 'holes');
L = bwlabel(bw);
imshow(label2rgb(L, 'jet', 'k', 'shuffle'))

bw = imbinarize(imread('text.png'));
sel = bwselect(bw, [60 120], [50 90], 8);
montage({bw, sel})

bw = imfill(imbinarize(imread('coins.png')), 'holes');
round_only = bwpropfilt(bw, 'Eccentricity', [0 0.5]);
montage({bw, round_only})

I = imread('cameraman.tif');
BW = edge(I, 'canny');
B = imoverlay(I, BW, 'red');
imshow(B)

I = imread('eight.tif');
xi = [60 180 200 100 60];
yi = [30 40 160 170 30];
BW = roipoly(I, xi, yi);
meanInRoi = mean(double(I(BW)));
imshow(labeloverlay(I, BW))

x = [20 120 150 60];
y = [30 25 140 150];
BW = poly2mask(x, y, 200, 200);
stats = regionprops(BW, 'Area', 'Centroid');
